.win-popup .popup-layout {position: relative; background: #fff;}

.win-popup .popup-layout .popup-layout-top {position: relative; padding: 18px 14px; border-bottom: 1px solid #dbdbdb; background: #2C939F;}
.win-popup .popup-layout .popup-layout-top h1 {font-size: 18px; font-weight: 500; color: #fff;}
.win-popup .popup-layout .popup-layout-top button {display: block; position: absolute; top: 0; right: 0; width: 53px; height: 53px; background: url(../images/content-icon/popup-close-btn.png) no-repeat center; background-size: 28px;}

.win-popup .popup-layout-content {overflow-y: auto; padding: 0px 0px 40px;}

.win-popup .popup-layout-content.popup-layout-in-btn {}
.win-popup .popup-layout-content .content-bottom-btn {position: fixed; bottom: 0; left: 0; padding: 18px 0; width: 100%; border-top: 1px solid #dbdbdb; background: #fff;}
.win-popup .popup-layout-content .content-bottom-btn a, .popup .popup-layout-content .content-bottom-btn button {min-width: auto; width: 134px;}
.win-popup .popup-layout-content .content-bottom-btn > div {margin: 0;}

.win-popup .popup-layout-content .popup-checkbox {position: absolute; right: 44px; top: 50%; transform: translateY(-50%); -webkit-transform: translateY(-50%);}
.win-popup .popup-layout-content .popup-checkbox input {display: inline-block; vertical-align: top;}
.win-popup .popup-layout-content .popup-checkbox p {display: inline-block; margin-left: 10px; font-size: 12px; color: #666; vertical-align: top;}

.select-layout {margin:10px 0;text-align:center}
.select-layout > div.radio-layout ul {display:inline-block;margin:0 auto;}
.select-layout > div.radio-layout ul li {float: left;}
.select-layout > div.radio-layout ul::after {display: block; clear: both; content: "";}
.select-layout > div.radio-layout ul li p {margin-bottom: 0; font-size: 14px; color: #666;}
.select-layout > div.radio-layout ul li + li {margin-left:10px;}
.select-layout > div.radio-layout ul li input[type="radio"] + label {line-height:14px}


