.process-step {overflow-x:auto;display:flex;align-items:center;position:relative;width:100%;height:100%;padding:10px 4px;box-sizing:border-box}
.process-step .w2group {background-color:transparent}
.process-step > ul {display:flex;position:relative;white-space:nowrap;width:100%;;margin-block-start:0;margin-block-end:0;padding-inline-start:0;padding-inline-end:0}
.process-step > ul > li {display:inline-flex;flex-direction:column;align-items:center;flex:1;position:relative;min-width:150px;height:176px;padding:20px 18px;border:1px solid #dbdbdb;background-color:#fff;box-sizing:border-box;cursor:pointer}
.process-step > ul > li + li {margin-left:18px}
.process-step > ul > li + li::before {content:'';display:block;position:absolute;top:50%;left:-26px;z-index:1;width:32px;height:32px;margin-top:-16px;border-radius:50%;background:#2c939f url(../images/content-icon/step-arrow.png) no-repeat 12px 50%;background-size:9px 15px}
.process-step > ul > li > span {display:inline-block;color:#666;font-size:16px}
.process-step > ul > li > .no {display:flex;align-items:center;justify-content:center;flex:none;width:36px;height:36px;border-radius:50%;background-color:#e7f6ff;color:#027cc2;line-height:1}
.process-step > ul > li > .tbx {display:flex;flex-direction:column;align-items:center;justify-content:space-between;flex:1;width:100%;margin-top:10px;box-sizing:border-box}
.process-step > ul > li > .tbx em {line-height:120%;text-align:center}
.process-step > ul > li .date {margin-top:14px;font-size:14px}
.process-step > ul > li.cmp {background-color:#fbfbfb}
.process-step > ul > li.cmp > .no {background-color:#f2f2f2;color:#666}
.process-step > ul > li.current {border:2px solid #027cc2;background-color:#e5fcff}
.process-step > ul > li.current > .no {background-color:#027cc2;color:#fff;font-size:20px;font-weight:600}
.process-step > ul > li .tooltip {display:block;visibility:hidden;position:absolute;top:93px;left:50%;z-index:2000;width:156px;margin-left:-78px;padding:10px;background:#027cc2;color:#fff;font-size:14px;letter-spacing:-0.28px;line-height:130%;white-space:normal;box-sizing:border-box;opacity:0;transition:all .5s cubic-bezier(0.68,0,0.265,0);text-shadow:none}
.process-step > ul > li:hover .tooltip {visibility:visible;top:95px;opacity:1}
.process-step > ul > li .tooltip::before {content:'';position:absolute;top:-5px;left:50%;margin-left:-3px;border-width:0 5px 5px 5px;border-style:solid;border-color:transparent transparent #027cc2 transparent}

.service-form > h2 {margin-bottom:16px;font-size:18px;font-weight:600;line-height:26px}

